import sympy as sp

QQ = sp.QQ
ZZ = sp.ZZ
x = sp.Symbol('x')

CONDITION_LABELS = [
    "H_1: E is an extension field of F",
    "H_2: alpha is algebraic over F",
    "not Q: kernel is not generated by a unique monic irreducible polynomial"
]

N_HYP = 2
NEG_Q_INDEX = 2

def conditions(witness):
    try:
        if isinstance(witness, tuple) and len(witness) == 3:
            F, E, alpha = witness
        else:
            F = ZZ
            E = QQ
            alpha = witness
    except Exception:
        return [False, False, False]
    
    h1 = False
    try:
        if F == ZZ and E == QQ:
            h1 = True
        elif hasattr(E, 'is_Field') and E.is_Field and hasattr(F, 'is_Field') and F.is_Field:
            h1 = True
    except Exception:
        h1 = False

    h2 = False
    try:
        if F in (QQ, ZZ):
            p = sp.minpoly(alpha, x)
            if p is not None and sp.degree(p, x) > 0:
                h2 = True
    except Exception:
        h2 = False

    neg_q = False
    try:
        alpha_in_E = True
        if E == QQ:
            if not sp.sympify(alpha).is_rational:
                alpha_in_E = False
        
        if not alpha_in_E:
            neg_q = True
        else:
            if F == ZZ:
                p = sp.minpoly(alpha, x)
                p_Z = sp.Poly(p, x, domain=QQ).clear_denoms()[1]
                if abs(p_Z.LC()) != 1:
                    neg_q = True
    except Exception:
        neg_q = False

    return [bool(h1), bool(h2), bool(neg_q)]